    pub mod memory_card_messages {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum MemoryCardMessages {
            InvalidMachine,
            SettingsLoaded,
            SettingsSaved,
            SettingsReset,
            SettingsCleared,
        }
        impl MemoryCardMessages {
            pub const VALUES: [MemoryCardMessages; 5] = [MemoryCardMessages::InvalidMachine, MemoryCardMessages::SettingsLoaded, MemoryCardMessages::SettingsSaved, MemoryCardMessages::SettingsReset, MemoryCardMessages::SettingsCleared, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    MemoryCardMessages::InvalidMachine => "INVALID_MACHINE",
                    MemoryCardMessages::SettingsLoaded => "SETTINGS_LOADED",
                    MemoryCardMessages::SettingsSaved => "SETTINGS_SAVED",
                    MemoryCardMessages::SettingsReset => "SETTINGS_RESET",
                    MemoryCardMessages::SettingsCleared => "SETTINGS_CLEARED",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "INVALID_MACHINE" => MemoryCardMessages::InvalidMachine,
                    "SETTINGS_LOADED" => MemoryCardMessages::SettingsLoaded,
                    "SETTINGS_SAVED" => MemoryCardMessages::SettingsSaved,
                    "SETTINGS_RESET" => MemoryCardMessages::SettingsReset,
                    "SETTINGS_CLEARED" => MemoryCardMessages::SettingsCleared,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

