    /// `SpatialPylonBlockEntity.AxisPosition` (appeng/blockentity/spatial/SpatialPylonBlockEntity.java)
    pub mod spatial_pylon_block_entity_axis_position {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum AxisPosition {
            None,
            Start,
            Middle,
            End,
        }
        impl AxisPosition {
            pub const VALUES: [AxisPosition; 4] = [AxisPosition::None, AxisPosition::Start, AxisPosition::Middle, AxisPosition::End, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    AxisPosition::None => "NONE",
                    AxisPosition::Start => "START",
                    AxisPosition::Middle => "MIDDLE",
                    AxisPosition::End => "END",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "NONE" => AxisPosition::None,
                    "START" => AxisPosition::Start,
                    "MIDDLE" => AxisPosition::Middle,
                    "END" => AxisPosition::End,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

