    /// `LytVisitor.Result` (appeng/client/guidebook/document/block/LytVisitor.java)
    pub mod lyt_visitor_result {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum Result_ {
            Continue,
            SkipChildren,
            Stop,
        }
        impl Result_ {
            pub const VALUES: [Result_; 3] = [Result_::Continue, Result_::SkipChildren, Result_::Stop, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    Result_::Continue => "CONTINUE",
                    Result_::SkipChildren => "SKIP_CHILDREN",
                    Result_::Stop => "STOP",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "CONTINUE" => Result_::Continue,
                    "SKIP_CHILDREN" => Result_::SkipChildren,
                    "STOP" => Result_::Stop,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

