    /// `CraftingJobStatusPacket.Status` (appeng/core/sync/packets/CraftingJobStatusPacket.java)
    pub mod crafting_job_status_packet_status {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum Status {
            Started,
            Cancelled,
            Finished,
        }
        impl Status {
            pub const VALUES: [Status; 3] = [Status::Started, Status::Cancelled, Status::Finished, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    Status::Started => "STARTED",
                    Status::Cancelled => "CANCELLED",
                    Status::Finished => "FINISHED",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "STARTED" => Status::Started,
                    "CANCELLED" => Status::Cancelled,
                    "FINISHED" => Status::Finished,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

