    pub mod generic_stack_inv_mode {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum Mode {
            ConfigTypes,
            ConfigStacks,
            Storage,
        }
        impl Mode {
            pub const VALUES: [Mode; 3] = [Mode::ConfigTypes, Mode::ConfigStacks, Mode::Storage, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    Mode::ConfigTypes => "CONFIG_TYPES",
                    Mode::ConfigStacks => "CONFIG_STACKS",
                    Mode::Storage => "STORAGE",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "CONFIG_TYPES" => Mode::ConfigTypes,
                    "CONFIG_STACKS" => Mode::ConfigStacks,
                    "STORAGE" => Mode::Storage,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

