    /// `SpatialPylonCluster.Axis` (appeng/me/cluster/implementations/SpatialPylonCluster.java)
    pub mod spatial_pylon_cluster_axis {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum Axis {
            X,
            Y,
            Z,
            Unformed,
        }
        impl Axis {
            pub const VALUES: [Axis; 4] = [Axis::X, Axis::Y, Axis::Z, Axis::Unformed, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    Axis::X => "X",
                    Axis::Y => "Y",
                    Axis::Z => "Z",
                    Axis::Unformed => "UNFORMED",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "X" => Axis::X,
                    "Y" => Axis::Y,
                    "Z" => Axis::Z,
                    "UNFORMED" => Axis::Unformed,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

