    /// `AdHocNetworkError` (appeng/me/service/AdHocNetworkError.java)
    pub mod ad_hoc_network_error {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum AdHocNetworkError {
            NestedP2pTunnel,
            TooManyChannels,
        }
        impl AdHocNetworkError {
            pub const VALUES: [AdHocNetworkError; 2] = [AdHocNetworkError::NestedP2pTunnel, AdHocNetworkError::TooManyChannels, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    AdHocNetworkError::NestedP2pTunnel => "NESTED_P2P_TUNNEL",
                    AdHocNetworkError::TooManyChannels => "TOO_MANY_CHANNELS",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "NESTED_P2P_TUNNEL" => AdHocNetworkError::NestedP2pTunnel,
                    "TOO_MANY_CHANNELS" => AdHocNetworkError::TooManyChannels,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

