    /// `EncodingMode` (appeng/parts/encoding/EncodingMode.java)
    pub mod encoding_mode {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum EncodingMode {
            Crafting,
            Processing,
            SmithingTable,
            Stonecutting,
        }
        impl EncodingMode {
            pub const VALUES: [EncodingMode; 4] = [EncodingMode::Crafting, EncodingMode::Processing, EncodingMode::SmithingTable, EncodingMode::Stonecutting, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    EncodingMode::Crafting => "CRAFTING",
                    EncodingMode::Processing => "PROCESSING",
                    EncodingMode::SmithingTable => "SMITHING_TABLE",
                    EncodingMode::Stonecutting => "STONECUTTING",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "CRAFTING" => EncodingMode::Crafting,
                    "PROCESSING" => EncodingMode::Processing,
                    "SMITHING_TABLE" => EncodingMode::SmithingTable,
                    "STONECUTTING" => EncodingMode::Stonecutting,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

