    pub mod platform_feature_detector {
        use super::*;
        #[derive(Clone, Debug)]
        pub struct PlatformFeatureDetector {
            pub is_running_on_android: Option<bool>,
        }
        impl PlatformFeatureDetector {
            pub fn new() -> Self {
                let mut s = Self { is_running_on_android: None };
                s
            }
            pub fn is_running_on_android(&mut self) -> bool {
                if self.is_running_on_android.is_none() {
                    let name: Option<String> = std::env::var("java.runtime.name").ok();
                    self.is_running_on_android = Some(name.is_some() && ((name.as_deref().expect("null")).starts_with("Android Runtime")));
                }
                return self.is_running_on_android.expect("null");
            }
        }
    }

